import {MOTOR_CLUB} from './motor-catalog.mjs?v=38';
import {CLUB,DAILY_STOPS} from './club-catalog.mjs?v=38';
import {DISTRICTS,LANDMARKS,BLOCKS,ROAD,LIMIT,HOME,STOPS,districtAt,closestRoad,route,dist,clamp} from './driving.mjs?v=38';
import {HOMES} from './social-catalog.mjs?v=38';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EXTENT=LIMIT+40,MAX_SPAN=EXTENT*2;
const palette={workshop:'#eead61',casino:'#f2c763',garage:'#efd269',pickup:'#80b750',drop:'#ef9465',waypoint:'#bba2db',home:'#d5a277',player:'#70cbd0'};
export function createCityAtlas(api){
 let filter='all',selected=null,center={x:0,z:0},span=MAX_SPAN,drag=null,query='',lastLive=0;
 const $=id=>document.getElementById(id);
 function pois(state){return [{...HOME,id:'garage',kind:'garage'},{...MOTOR_CLUB,kind:'workshop',description:'Rae’s workshop and car meet. Eight display bays, custom parts, lounge seating, and cooperative convoy jobs. Stop at the rolling doors and press E.'},{...CLUB,kind:'casino',description:'The green-and-gold casino across from Last Exit Garage. Stop at the carpeted west entrance and press E. Free-play cards, chat and emotes.'},...DAILY_STOPS.map(s=>({...s,id:'daily-'+s.id,kind:'waypoint',description:s.action+' to earn materials for your home.'})),...LANDMARKS.map(p=>({...p,kind:'waypoint'})),...HOMES.map(h=>({...h,kind:'home',name:(state.home?.homeId===h.id?'YOUR HOME · ':'')+h.name})),...state.jobs.map(j=>({...STOPS.find(p=>p.id===j.id),kind:'pickup',job:j.job})),...state.passengers.map(j=>({...j.dest,id:j.id,kind:'drop',job:j})),...(state.peers||[]).map(p=>({...p,id:'player-'+p.id,kind:'player',name:p.name+(p.mode==='driving'?' · DRIVING':' · '+p.mode.toUpperCase())}))];}
 const shown=p=>(filter==='all'||filter==='casino'&&p.kind==='casino'||filter==='workshop'&&p.kind==='workshop'||filter==='jobs'&&['pickup','drop'].includes(p.kind)||filter==='districts'&&p.kind==='waypoint'||filter==='homes'&&p.kind==='home'||filter==='players'&&p.kind==='player')&&(!query||p.name.toLowerCase().includes(query.toLowerCase()));
 const kindName=p=>({workshop:'MOTOR CLUB',casino:'CASINO',garage:'GARAGE',pickup:'PICKUP',drop:'DROP-OFF',waypoint:'DISTRICT',home:'HOME',player:'PLAYER'}[p.kind]);
 function marker(p){
  const size=clamp(span/72,4,10),color=palette[p.kind]||'#efd269';
  const icon=p.kind==='workshop'?'<path d="M-3-3L3 3M-3 3L3-3" stroke="#284b60" stroke-width="2"/>':p.kind==='casino'?'<path d="M0-3L2.6 0L0 3L-2.6 0Z" fill="#284b3c"/>':p.kind==='home'?'<path d="M-3 0L0-3L3 0V3H-3Z" fill="#30402b"/>':p.kind==='player'?'<circle cy="-1.5" r="1.8" fill="#243930"/><path d="M-3 3Q0-2 3 3" fill="#243930"/>':p.kind==='garage'?'<path d="M-3 0H3V2H-3ZM-2-2H2L3 0H-3Z" fill="#3b3724"/>':p.kind==='pickup'?'<path d="M-3 0H3M0-3V3" stroke="#2c4129" stroke-width="1.5"/>':p.kind==='drop'?'<path d="M-3 0L-1 2L3-2" stroke="#482e24" stroke-width="1.6" fill="none"/>':'<path d="M0-3L3 0L0 3L-3 0Z" fill="#443d58"/>';
  return '<g transform="translate('+p.x+' '+p.z+')"><rect x="'+(-size-1)+'" y="'+(-size-1)+'" width="'+(size*2+2)+'" height="'+(size*2+2)+'" fill="#32412d"/><rect x="'+(-size)+'" y="'+(-size)+'" width="'+(size*2)+'" height="'+(size*2)+'" fill="'+color+'"/><g transform="scale('+(size/4)+')">'+icon+'</g><title>'+esc(p.name)+'</title></g>';
 }
 function peers(state){return pois(state).filter(p=>p.kind==='player'&&shown(p)).map(marker).join('');}
 function svg(state){
  const points=selected?route(state.origin,selected):state.route,edge=LIMIT+2;
  const roads=ROAD.map(n=>'M'+(-edge)+' '+n+'H'+edge+' M'+n+' '+(-edge)+'V'+edge).join(' ');
  const line=(points||[]).map((p,i)=>(i?'L':'M')+p.x+' '+p.z).join(' ');
  return '<svg id="atlasMap" viewBox="'+[center.x-span/2,center.z-span/2,span,span].join(' ')+'" role="img" aria-label="GETAWAY city map: parks, streets, homes, jobs, and online players. Drag to pan and select a destination.">'+
  '<defs><pattern id="mapWater" width="22" height="22" patternUnits="userSpaceOnUse"><rect width="22" height="22" fill="#8fbfc8"/><path d="M2 6h6m4 8h6" stroke="#bbdbe0" stroke-width="1"/></pattern><pattern id="mapPark" width="9" height="9" patternUnits="userSpaceOnUse"><rect width="9" height="9" fill="#9fca78"/><rect x="2" y="3" width="2" height="2" fill="#729f5d"/></pattern></defs>'+
  '<rect x="-1000" y="-1000" width="2000" height="2000" fill="url(#mapWater)"/><rect x="'+(-edge-3)+'" y="'+(-edge-3)+'" width="'+(edge*2+6)+'" height="'+(edge*2+6)+'" fill="#e7d7b1" stroke="#688f8b" stroke-width="4"/>'+
  DISTRICTS.map((d,i)=>{const bounds=i<9?[d.x-90,d.z-90,180,180]:i===9?[-390,-390,780,108]:i===11?[-390,282,780,108]:i===10?[282,-282,108,564]:[-390,-282,108,564];return '<rect x="'+bounds[0]+'" y="'+bounds[1]+'" width="'+bounds[2]+'" height="'+bounds[3]+'" fill="'+d.color+'" opacity=".28"/>';}).join('')+
  '<path d="'+roads+'" stroke="#d6c8a8" stroke-width="15.5"/><path d="'+roads+'" stroke="#fff9e8" stroke-width="11.8"/><path d="'+roads+'" stroke="#d5cbb2" stroke-width=".65" stroke-dasharray="3 3"/>'+
  BLOCKS.map(b=>{const area=districtAt(b),fill=b.park?'url(#mapPark)':area.type==='garden'?'#b5d692':area.type==='residential'?'#dbb58d':area.type==='industrial'?'#aab9b2':'#c3b5a4';return '<g><rect x="'+(b.x-b.w/2)+'" y="'+(b.z-b.d/2)+'" width="'+b.w+'" height="'+b.d+'" fill="'+fill+'" stroke="'+(b.park?'#6c9452':'#9b987e')+'" stroke-width=".6"/>'+(b.park?'<path d="M'+(b.x-b.w/2)+' '+b.z+'h'+b.w+' M'+b.x+' '+(b.z-b.d/2)+'v'+b.d+'" stroke="#e6dec0" stroke-width="2"/>':'<path d="M'+(b.x-b.w/2+3)+' '+(b.z-b.d/2+3)+'h'+(b.w-6)+'v'+(b.d-6)+'h-'+(b.w-6)+'Z" fill="none" stroke="#fff1d0" stroke-width=".7"/>')+'</g>';}).join('')+
  DISTRICTS.map(d=>'<text x="'+d.x+'" y="'+(d.z-43)+'" text-anchor="middle" fill="#40563c" font-family="Arial,sans-serif" font-size="'+(span>550?9:6.5)+'" font-weight="900" letter-spacing="1" stroke="#f6edcb" stroke-width="2.7" paint-order="stroke">'+d.name+'</text>').join('')+
  '<path d="'+line+'" fill="none" stroke="#574533" stroke-width="5.5" stroke-linejoin="round"/><path d="'+line+'" fill="none" stroke="#ffcb55" stroke-width="3.7" stroke-linejoin="round"/>'+
  pois(state).filter(p=>p.kind!=='player'&&shown(p)).map(marker).join('')+'<g id="atlasPeers">'+peers(state)+'</g>'+
  (selected?'<rect x="'+(selected.x-13)+'" y="'+(selected.z-13)+'" width="26" height="26" fill="none" stroke="#3c4529" stroke-width="2" stroke-dasharray="5 2"/>':'')+
  '<g transform="translate('+state.origin.x+' '+state.origin.z+') rotate('+(-state.origin.heading*180/Math.PI||0)+')"><circle r="8" fill="#fff4c6" stroke="#273e34" stroke-width="2"/><path d="M0 6L-4-4L0-2L4-4Z" fill="#2c746d"/></g></svg>';
 }
 function render(){
  const state=api.state(),list=pois(state).filter(shown),distance=selected?Math.round(route(state.origin,selected).reduce((n,p,i,a)=>n+(i?dist(a[i-1],p):0),0)):0;
  api.modal('<button class="modal-close" data-close aria-label="Close city map">×</button><header class="atlas-heading"><span>GETAWAY / EXPLORER’S MAP</span><h2 id="dialogTitle">YOUR NEXT DETOUR.</h2><p>'+DISTRICTS.length+' neighborhoods · '+ROAD.length**2+' junctions · '+(state.room?'SERVER '+esc(state.room):state.driving?'YOUR DRIVE IS PAUSED':'EXPLORE THE CITY')+'</p></header><div class="atlas-layout"><div class="atlas-cartography"><div class="atlas-tools"><button id="atlasOut" aria-label="Zoom out">−</button><button id="atlasIn" aria-label="Zoom in">+</button><button id="atlasFit">FULL CITY</button><button id="atlasLocate">FIND ME</button><b>N ↑</b></div><div class="atlas-map-wrap">'+svg(state)+'</div><div class="atlas-scale"><span>'+Math.round(span/4)+' m ━━━</span><b>'+Math.round(MAX_SPAN/span*100)+'%</b><span>W ← · → E</span></div><div class="atlas-legend">'+Object.entries(palette).map(([k,c])=>'<span><i style="background:'+c+'"></i>'+({workshop:'Motor Club',casino:'Casino',garage:'Garage',pickup:'Pickup',drop:'Drop-off',waypoint:'District',home:'Home',player:'Player'}[k])+'</span>').join('')+'</div><p class="atlas-hint">Drag to explore · wheel or + / − to zoom · click a place or road</p></div><aside class="atlas-sidebar"><form id="atlasSearch" class="atlas-search"><label for="atlasQuery">FIND A PLACE</label><div><input id="atlasQuery" maxlength="40" value="'+esc(query)+'" placeholder="Motor Club, casino, home…"><button type="submit" aria-label="Search map">GO</button></div></form><div class="atlas-filters">'+[['all','All'],['casino','Casino'],['workshop','Motor Club'],['jobs','Jobs'],['homes','Homes'],['districts','Districts'],['players','Players']].map(([id,label])=>'<button data-atlas-filter="'+id+'" aria-pressed="'+(filter===id)+'">'+label+'</button>').join('')+'</div><div class="atlas-places">'+(list.length?list.map(p=>'<button data-atlas-poi="'+esc(p.kind+':'+p.id)+'" aria-pressed="'+(selected?.id===p.id)+'"><i style="background:'+palette[p.kind]+'"></i><span>'+esc(p.name)+'</span><small>'+kindName(p)+' · '+Math.round(dist(state.origin,p))+' m</small></button>').join(''):'<p class="atlas-empty">'+(filter==='players'?'No other players here. Join a neighborhood from ONLINE.':'No matching places. Try another search.')+'</p>')+'</div><div class="atlas-selection"><span>'+(selected?'DESTINATION':'YOU ARE HERE')+'</span><h3>'+esc(selected?.name||districtAt(state.origin).name)+'</h3><p>'+esc(selected?selected.description||districtAt(selected).description:'Pick a marker to plan your next stop.')+'</p>'+(selected?'<b>'+distance+' m BY ROAD · '+Math.max(1,Math.ceil(distance/20))+' s CRUISE</b><button id="atlasGo" class="primary">SET GPS ROUTE →</button>':'')+'<button id="atlasClear" class="small-btn">CLEAR ROUTE</button></div></aside></div>',true);
  $('modalRoot').classList.add('atlas-shade');
  $('atlasSearch').onsubmit=e=>{e.preventDefault();query=$('atlasQuery').value.trim();render();};
  document.querySelectorAll('[data-atlas-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.atlasFilter;render()});
  document.querySelectorAll('[data-atlas-poi]').forEach(b=>b.onclick=()=>{selected=pois(api.state()).find(p=>p.kind+':'+p.id===b.dataset.atlasPoi);if(!selected)return;center={x:selected.x,z:selected.z};span=180;render()});
  const zoom=f=>{span=clamp(span*f,90,MAX_SPAN);render();};
  $('atlasIn').onclick=()=>zoom(1/1.5);$('atlasOut').onclick=()=>zoom(1.5);
  $('atlasFit').onclick=()=>{span=MAX_SPAN;center={x:0,z:0};render()};
  $('atlasLocate').onclick=()=>{center={...state.origin};span=180;render()};
  $('atlasClear').onclick=()=>{selected=null;api.clear();render()};
  if(selected)$('atlasGo').onclick=()=>api.navigate({...selected,x:selected.x,z:selected.z});
  const map=$('atlasMap');
  map.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.3:1/1.3);},{passive:false});
  map.addEventListener('pointerdown',e=>{if(e.button&&e.button!==0)return;drag={x:e.clientX,y:e.clientY,center:{...center}};map.setPointerCapture?.(e.pointerId)});
  map.addEventListener('pointermove',e=>{if(!drag)return;const r=map.getBoundingClientRect(),scale=span/r.width;center={x:clamp(drag.center.x-(e.clientX-drag.x)*scale,-LIMIT,LIMIT),z:clamp(drag.center.z-(e.clientY-drag.y)*scale,-LIMIT,LIMIT)};map.setAttribute('viewBox',[center.x-span/2,center.z-span/2,span,span].join(' '))});
  map.addEventListener('pointerup',e=>{if(!drag)return;const moved=Math.hypot(e.clientX-drag.x,e.clientY-drag.y);drag=null;if(moved<6){const r=map.getBoundingClientRect(),point={x:center.x+(e.clientX-r.left)/r.width*span-span/2,z:center.z+(e.clientY-r.top)/r.height*span-span/2};const near=pois(api.state()).filter(shown).sort((a,b)=>dist(a,point)-dist(b,point)).find(p=>dist(p,point)<span*.024);selected=near||{...closestRoad(point),id:'custom',kind:'waypoint',name:'STREET WAYPOINT'};}render()});
  map.addEventListener('pointercancel',()=>{drag=null;render()});
 }
 return {open(){selected=null;center={x:0,z:0};span=MAX_SPAN;filter='all';query='';render()},isOpen:()=>document.getElementById('modalRoot')?.classList.contains('atlas-shade'),update(now){if(!document.getElementById('modalRoot')?.classList.contains('atlas-shade')||now-lastLive<1000||!$('atlasPeers'))return;lastLive=now;$('atlasPeers').innerHTML=peers(api.state());}};
}

